<?php
// Monster class:
// ($lvl, $class, $str, $agi, $int, $wit, $luck, $dmg_min, $dmg_max, $hp, $armor, $id, $exp, $weapon_id, $shield_id = 0)

//base entity with nothing more than base stats
//base for simulator
class Entity{

	//DB player ID, monster ID, and what not to display in fight correctly
	public $ID;

	//used for simulator
	public $hp;

	public $maxHp;

	public $class;
	public $lvl;

	protected $baseStats = [
	"str" => "0",
	"dex" => "0",
	"int" => "0",
	"wit" => "0",
	"luck" => "0"];

	//dmg range
	public $dmg_min;
	public $dmg_max;

	//block/dodge chance, range 1-100, 0 = no dodge/block
	public $block;

	//crit chance, float? tbd
	public $crit;

	//items shown in fights
	public $weapon;
	public $shield;
	
	// armor
	public $armor;

	function __construct(){
		$this->NewEntity();
	}
	
	//sets hp based on lvl, stats etc	
	public function NewEntity(){

		if($this->class == 1)
			$this->maxHp = $this->getTotalStats()['wit'] * 5 * ($this->lvl + 1);
		else if($this->class == 2)
			$this->maxHp = $this->getTotalStats()['wit'] * 2 * ($this->lvl + 1);
		else  
			$this->maxHp = $this->getTotalStats()['wit'] * 4 * ($this->lvl + 1);

		$this->hp = $this->maxHp;

		//TODO: delete this later
		$this->crit = 50;
	}

	//used for simulation
	public function dmg($dmg){
		$this->hp -= $dmg;
	}

	//in case i need to reset for simulations
	public function resetHp(){
		$this->hp = $this->maxHp;
	}

	//override in subclasses, to add equipstats
	public function getTotalStats(){
		return $this->baseStats;
	}

	public static function getStatName($index){
		switch($index){
			case 1:
				return "str";
				break;
			case 2:
				return "dex";
				break;
			case 3:
				return "int";
				break;
			case 4:
				return "wit";
				break;
			case 5:
				return "luck";
				break;
		}
	}
}

//dungeon monsters, maybe quest monsters?
class Monster extends Entity{

	public $exp;
	public $gold;
	public $weaponID;
	public $ID2;


	function __construct($lvl, $class, $str, $agi, $int, $wit, $luck, $dmg_min, $dmg_max, $hp, $armor, $id, $exp, $weapon_id, $shield_id = 5){
		$this->lvl = $lvl;
		$this->class = $class;
		$this->baseStats['str'] = $str;
		$this->baseStats['dex'] = $agi;
		$this->baseStats['int'] = $int;
		$this->baseStats['wit'] = $wit;
		$this->baseStats['luck'] = $luck;

		$this->hp = $hp;
		$this->maxHp = $hp;

		$this->dmg_min = $dmg_min;
		$this->dmg_max = $dmg_max;

		$this->armor = $armor;

		$this->ID = $id;
		if($id>0)
			$this->ID *= -1;
		
		$this->ID2 = $this->ID;

		$this->exp = $exp;

		$this->weaponID = $weapon_id;

		if($this->class == 1){
			if($shield_id > 0){
				$this->block = 25;
				$this->shield = $shield_id;
			}
		}else if($this->class == 3){
			$this->block = 50;
			// $mainStat = "dex";
		}else{
			$this->block = 0;
			// $mainStat = "int";
		}

		//temporary
		$this->crit = 25;

	}

	//temp shit, buffs the mob to dark zone status 
	public function buff(){
		$this->maxHp += 10000000;
		$this->hp = $this->maxHp;
		$this->dmg_min += 1000000;
		$this->dmg_max += 1500000;
		$this->baseStats['str'] += 5000;
		$this->baseStats['dex'] += 5000;
		$this->baseStats['int'] += 5000;
		$this->baseStats['wit'] += 5000;
		$this->baseStats['luck'] += 5000;
		$this->lvl += 100;}
	
	public function raidbuff($boss) {
		
		//By Jack
		//Guild raid lvl 50-100
		if($boss) {
			$this->maxHp += 4000000;
			$this->hp = $this->maxHp;
			$this->baseStats['wit'] += 30000;
		}
		$this->dmg_min *= 8;
		$this->dmg_max *= 10;
		$this->lvl += 356;
		//Add some random things, we don't right data - Jack
		$this->baseStats['str'] += 24;
		$this->baseStats['dex'] += 36;
		$this->baseStats['int'] += 51;
		$this->baseStats['wit'] += 68;
		$this->baseStats['luck'] += 10;
		
	}

	public function raidbuff2($boss) {
		
		//By Jack
		//Guild raid shit 100-150 lvl - Difficulty: Hard
		//100% random, no data 
		
		if($boss) {
			$this->maxHp += 12000000;
			$this->hp = $this->maxHp;
			$this->baseStats['wit'] += 50000;
		}
		$this->maxHp += 4000000;
			$this->hp = $this->maxHp;
		$this->dmg_min *= 1010;
		$this->dmg_max *= 1290;
		$this->lvl += 532;
		
		$this->baseStats['str'] *= 116;
		$this->baseStats['dex'] *= 108;
		$this->baseStats['int'] *= 101;
		$this->baseStats['wit'] *= 129;
		$this->baseStats['luck'] *= 110;
		
	}
	
	public function convertToMyPet()
	{
		$this->ID2 = $this->ID;
		$this->ID = 100000;
	}

	public function getFightHeader(){

		$ret = [];
		for($i = 0; $i < 47; $i++)
			$ret[] = 0;

		$ret[47] = "";

		$ret[0] = $this->ID;
		$ret[1] = 0;
		$ret[2] = $this->lvl;
		$ret[3] = $this->maxHp;
		$ret[4] = $this->hp;
		$ret[5] = $this->baseStats['str'];
		$ret[6] = $this->baseStats['dex'];
		$ret[7] = $this->baseStats['int'];
		$ret[8] = $this->baseStats['wit'];
		$ret[9] = $this->baseStats['luck'];
		$ret[10] = abs($this->ID2) * -1;
		$ret[11] = 0;
		$ret[12] = 0;
		$ret[13] = 0;
		$ret[14] = 0;
		$ret[15] = 0;
		$ret[16] = 0;
		$ret[17] = 0;
		$ret[18] = 0;
		$ret[19] = 0;
		$ret[20] = 0;
		$ret[21] = 0;

		//weapon type
		$ret[22] = 1;

		//weapon id, if weapon is an item, 23 = 1 and 24 = item_id, else 23 is hittype
		if ($this->weaponID == 65535)
			$ret[23] = 65535; // Pet is my bitch
		else if ($this->weaponID > 0){
			$ret[23] = 1;
			$ret[24] = $this->weaponID;
		}else{
			$ret[23] = $this->weaponID;
		}


		$ret[25] = 0;
		$ret[26] = 0;
		$ret[27] = 0;
		$ret[28] = 0;
		$ret[29] = 0;
		$ret[30] = 0;
		$ret[31] = 0;
		$ret[32] = 0;
		$ret[33] = 0;
		$ret[34] = 0;
		$ret[35] = 2;
		$ret[36] = 5;
		$ret[37] = 0;
		$ret[38] = 0;
		$ret[39] = 0;
		$ret[40] = 0;
		$ret[41] = 0;
		$ret[42] = 0;
		$ret[43] = 0;
		$ret[44] = 0;
		$ret[45] = 0;
		$ret[46] = 0;

		return join("/", $ret);
	}
	
